/// Errors that may be returned by the TokenSwap program.
use anchor_lang::prelude::*;

#[error_code]
pub enum ErrorCode {
    #[msg("Not approved")]
    NotApproved,
    /// The owner of the input isn't set to the program address generated by the
    /// program.
    #[msg("Input account owner is not the program address")]
    InvalidOwner,
    /// The input token account is empty.
    #[msg("Input token account empty")]
    EmptySupply,
    /// The input token is invalid for swap.
    #[msg("InvalidInput")]
    InvalidInput,
    /// Address of the provided pool token mint is incorrect
    #[msg("Address of the provided lp token mint is incorrect")]
    IncorrectLpMint,
    /// Exceeds desired slippage limit
    #[msg("Exceeds desired slippage limit")]
    ExceededSlippage,
    /// Given pool token amount results in zero trading tokens
    #[msg("Given pool token amount results in zero trading tokens")]
    ZeroTradingTokens,
    #[msg("Not support token_2022 mint extension")]
    NotSupportMint,
    #[msg("invaild vault")]
    InvalidVault,
    #[msg("Init lp amount is too less(Because 100 amount lp will be locked)")]
    InitLpAmountTooLess,
    #[msg("TransferFee calculate not match")]
    TransferFeeCalculateNotMatch,
    #[msg("Math overflow")]
    MathOverflow,
    #[msg("Insufficient vault")]
    InsufficientVault,
    #[msg("Invalid fee model")]
    InvalidFeeModel,
    #[msg("Fee is zero")]
    NoFeeCollect,
    /// memetics.finance: the tier's swap guard is on and another program called the swap
    /// (states/config.rs refuses_swap). Last, so every code above keeps its number.
    #[msg("This pool's swaps must be sent directly, not called by another program")]
    SwapNotDirect,
    /// memetics.finance, 2026-11-14: `resign_keeper` signed by someone who is not the tier's
    /// keeper (lib.rs). After SwapNotDirect, so every code above keeps its number.
    #[msg("Only this fee tier's keeper can resign as its keeper")]
    NotKeeper,
    /// memetics.finance, 2026-11-14: update_config.rs param 9 named a key that is not a
    /// wallet's (states/config.rs `may_name_keeper`).
    #[msg("A keeper must be a wallet, not a program's address")]
    KeeperNotAWallet,
    /// memetics.finance, 2026-11-15: lib.rs `sweep_fees` was handed a destination that is not
    /// the fee owner's own associated token account for that coin, or one its owner gave away.
    /// After KeeperNotAWallet, so every code above keeps its number.
    #[msg("A swept fee goes only to its owner's own token account")]
    NotFeeOwnersAccount,
}
